select '8d62d777-8090-44bd-96a7-4dbe3e572e0f', 'nuevo_seguidor', 'follow', array_agg(f.seguidor_id order by f.created_at desc), count(*), '{}'::jsonb, false, now() - interval '2 hours', now() - interval '2 hours'
  from (select * from social.follows where seguido_id = '8d62d777-8090-44bd-96a7-4dbe3e572e0f' order by created_at desc limit 5) f;
select '8d62d777-8090-44bd-96a7-4dbe3e572e0f', 'novedad', array['7971a522-ff35-44ca-8a76-35eec93534d2'::uuid], jsonb_build_object('post_id', p.id, 'titulo', p.titulo), true, p.created_at, p.created_at
  from feed.posts p where p.tipo = 'novedad_oficial' order by p.created_at desc limit 3;

commit;
set session_replication_role = origin;

-- Cola de indexado del Orientador (el indexador la procesa por cron)
select pgmq.send('embeddings', jsonb_build_object('source_tipo', 'post', 'source_id', id)) from feed.posts where not oculto and visibilidad = 'socios';
select pgmq.send('embeddings', jsonb_build_object('source_tipo', 'perfil', 'source_id', user_id)) from profiles.profiles where acepta_sugerencias;
analyze identity.members, profiles.profiles, profiles.experiences, social.follows, feed.posts, feed.comments, feed.recommendations, clubs.clubs, clubs.club_members, clubs.events, messaging.conversations, messaging.conversation_members, messaging.messages, notifications.notifications;
